667:   private deleteSettingFromFile(path: string, key: string): void {
668:     this.clearHookOrigins();
669:     // Must be YAML-aware, symmetric with saveProjectSetting: a project with only
670:     // settings.yaml has no .json, so the old `existsSync(path)` guard returned
671:     // here and the override survived (read/merge ARE yaml-aware → UI shows
672:     // "inherited" but the key still applies). readJsonObject resolves the sibling
673:     // YAML; the cleaned object is written back as JSON (JSON is the write-back
674:     // format and wins over YAML, exactly as save does).
675:     if (!resolveConfigPath(path)) return;
676:     this.mutateSettingsFile(path, (current) => {
677:       const parts = parseDottedSettingKey(key);
678:       let target: Record<string, unknown> | undefined = current;
679:       for (let i = 0; i < parts.length - 1; i++) {
680:         const seg = parts[i]!;
681:         // Intermediate segment missing → nothing to delete; skip the write
682:         // entirely rather than rewriting the file unchanged.
683:         if (!target || !isOwnPlainObject(target, seg)) return false;
684:         target = target[seg] as Record<string, unknown>;
685:       }
686:       if (target) delete target[parts[parts.length - 1]!];
687:       return true;
688:     });
689:     this.invalidate();
690:   }
