1: /**
2:  * Capability-control descriptor types.
3:  *
4:  * A read-only projection layer over the four extension-capability loaders
5:  * (builtin tools, MCP servers, skills, plugins). A CapabilityDescriptor is a
6:  * computed view, never a source of truth — the truth stays in the loaders +
7:  * settings. Each descriptor carries an inlined `control` describing how to
8:  * toggle it, so the switch router never has to branch on `kind`.
9:  *
10:  * See docs/superpowers/specs/2026-05-29-capability-control-design.md
11:  */
12: 
13: /** A uniform, read-only projection of one extension capability. */
14: export interface CapabilityDescriptor {
15:   /** Globally unique; the source prefix isolates the namespace. */
16:   id: string;
17:   kind: "builtin" | "mcp" | "skill" | "plugin" | "agent";
18:   /** Display name: builtin=tool, mcp=server, skill=skill, plugin=plugin, agent=role. */
19:   name: string;
20:   /** One-line description pulled from the underlying metadata. */
21:   description: string;
22:   /** Computed from preset defaults + the relevant switch config. */
23:   enabled: boolean;
24:   /** Which settings key the switch writes, and how. */
25:   control: CapabilityControl;
26:   /** user/global baseline enablement, before any project overlay. */
27:   globalEnabled?: boolean;
28:   /** Project overlay state in a project-scope view. Absent === inherit. */
29:   projectOverride?: "on" | "off";
30:   /** Where the effective `enabled` value came from. */
31:   effectiveSource?: "user" | "project" | "default";
32:   /** Source details for UI grouping / navigation. */
33:   origin?: {
34:     serverName?: string;
35:     pluginName?: string;
36:     filePath?: string;
37:     toolCount?: number;
38:     isReadOnly?: boolean;
39:   };
40: }
41: 
42: /** Describes which settings key the switch writes and the write semantics. */
43: export interface CapabilityControl {
44:   settingsKey:
45:     | "agent.enabledBuiltinTools"
46:     | "agent.disabledBuiltinTools"
47:     | "mcpServers"
48:     | "disabledSkills"
49:     | "disabledPlugins"
50:     | "disabledAgents";
51:   /**
52:    *  - "denylist"    → off = token present in array (disabled*); on = removed
53:    *  - "allowlist"   → on  = token present in array (enabled*); off = removed
54:    *  - "record-flag" → flip mcpServers[token].enabled
55:    */
56:   mode: "denylist" | "allowlist" | "record-flag";
57:   /** Identifier written into the array, or used as the record key. */
58:   token: string;
59: }
